new_iter_end = """    def __iter__(self):
        yield self.major
        yield self.minor
        yield self.patch
        yield self.prerelease
        yield self.build

    def bump_major(self):
        \"\"\"Return a new VersionInfo with major incremented.\"\"\"
        return VersionInfo(self._major + 1, 0, 0)

    def bump_minor(self):
        \"\"\"Return a new VersionInfo with minor incremented.\"\"\"
        return VersionInfo(self._major, self._minor + 1, 0)

    def bump_patch(self):
        \"\"\"Return a new VersionInfo with patch incremented.\"\"\"
        return VersionInfo(self._major, self._minor, self._patch + 1)

    def bump_prerelease(self, token='rc'):
        \"\"\"Return a new VersionInfo with prerelease incremented.\"\"\"
        if self._prerelease is None:
            return VersionInfo(self._major, self._minor, self._patch, token + '1')
        parts = self._prerelease.split('.', 1)
        if len(parts) == 2:
            prefix, num_str = parts
            try:
                num = int(num_str)
                return VersionInfo(self._major, self._minor, self._patch,
                                   prefix + '.' + str(num + 1))
            except ValueError:
                return VersionInfo(self._major, self._minor, self._patch,
                                   self._prerelease + '.1')
        else:
            try:
                num = int(self._prerelease)
                return VersionInfo(self._major, self._minor, self._patch,
                                   str(num + 1))
            except ValueError:
                return VersionInfo(self._major, self._minor, self._patch,
                                   self._prerelease + '.1')

    def bump_build(self):
        \"\"\"Return a new VersionInfo with build incremented.\"\"\"
        if self._build is None:
            return VersionInfo(self._major, self._minor, self._patch,
                               self._prerelease, '1')
        parts = self._build.split('.', 1)
        if len(parts) == 2:
            prefix, num_str = parts
            try:
                num = int(num_str)
                return VersionInfo(self._major, self._minor, self._patch,
                                   self._prerelease, prefix + '.' + str(num + 1))
            except ValueError:
                return VersionInfo(self._major, self._minor, self._patch,
                                   self._prerelease, self._build + '.1')
        else:
            try:
                num = int(self._build)
                return VersionInfo(self._major, self._minor, self._patch,
                                   self._prerelease, str(num + 1))
            except ValueError:
                return VersionInfo(self._major, self._minor, self._patch,
                                   self._prerelease, self._build + '.1')

    def replace(self, **kwargs):
        \"\"\"Return a new VersionInfo with replaced components.\"\"\"
        d = self._asdict()
        for key, value in kwargs.items():
            if key in d:
                d[key] = value
        return VersionInfo(**d)

